Session.OpenModelRequestClosedBeforeLeav.source:
({ before, after, events }) => {
			if (
				before._tag !== "Running" ||
				before.open_model_request_id === null ||
				(after._tag === "Running" && after.turn === before.turn)
			) {
				return true
			}
			const endIndex = events.findIndex(
				(event) =>
					event._tag === "span.model_request_end" &&
					event.model_request_start_id === before.open_model_request_id,
			)
			const leaveIndex = events.findIndex(
				(event) =>
					event._tag === "session.status_idle" || event._tag === "session.status_terminated",
			)
			return endIndex >= 0 && (leaveIndex < 0 || endIndex < leaveIndex)
		}

Sessions.SessionViewMatchesSession.source:
(m) =>
			[
				m.Session.every((s) => {
					const view = m.SessionView.find((v) => v.id === s.id)
					if (s.state._tag === "Uninitialized") return view === undefined
					if (view === undefined) return false
					if (s.state._tag === "Idle") {
						return [
							view.state.id === s.id,
							view.state.status === "idle",
							view.state.turn === s.state.turn,
							!view.state.archived_at,
						].every((ok) => ok)
					}
					if (s.state._tag === "Running") {
						return [
							view.state.id === s.id,
							view.state.status === "running",
							view.state.turn === s.state.turn,
							!view.state.archived_at,
						].every((ok) => ok)
					}
					return [
						view.state.id === s.id,
						view.state.status === "terminated",
						!!view.state.archived_at === s.state.archived,
					].every((ok) => ok)
				}),
				m.SessionView.every((v) =>
					m.Session.some((s) =>
						[s.id === v.id, s.state._tag !== "Uninitialized"].every((ok) => ok),
					),
				),
			].every((ok) => ok)

Sessions.TurnInputMatchesSession.source:
(m) =>
			[
				m.Session.every((s) => {
					const view = m.TurnInput.find((v) => v.id === s.id)
					const sessionView = m.SessionView.find((v) => v.id === s.id)
					if (s.state._tag === "Uninitialized") return view === undefined
					if (view === undefined || sessionView === undefined) return false
					const common = [
						view.state.agent_id === sessionView.state.agent_id,
						view.state.agent_version === sessionView.state.agent_version,
						view.state.environment_id === sessionView.state.environment_id,
						view.state.turn === sessionView.state.turn,
					]
					if (s.state._tag === "Idle") {
						return [
							...common,
							view.state.turn === s.state.turn,
							view.state.input.length === 0,
							view.state.unsent.length <= 8,
						].every((ok) => ok)
					}
					if (s.state._tag === "Running") {
						return [
							...common,
							view.state.turn === s.state.turn,
							view.state.input.length >= 1,
							view.state.unsent.length === s.state.pending_user_messages,
						].every((ok) => ok)
					}
					return [...common, view.state.input.length === 0, view.state.unsent.length === 0].every(
						(ok) => ok,
					)
				}),
				m.TurnInput.every((v) =>
					m.Session.some((s) =>
						[s.id === v.id, s.state._tag !== "Uninitialized"].every((ok) => ok),
					),
				),
			].every((ok) => ok)
